<template><section class="selfie-panel"><h3>셀피 확인</h3><div v-if="!requested"><input v-model="requestReason" maxlength="500" placeholder="회원에게 안내할 요청 사유"/><button type="button" :disabled="busy||!requestReason.trim()" @click="requestSelfie">셀피 요청</button></div><button v-else type="button" :disabled="busy" @click="cancelRequest">셀피 요청 취소</button><p>{{labels[data?.state]||'셀피 미제출'}} <button type="button" @click="load" :disabled="busy">새로고침</button></p><p v-if="data">촬영 요청: {{data.challenge}}<br/>{{data.note}}</p><div v-if="data?.photosAvailable" class="compare"><figure><img tabindex="0" role="button" title="사진 확대" style="cursor:zoom-in" v-if="reference" :src="reference" alt="셀피 제출 당시 대표 사진"/><figcaption>제출 당시 대표 사진</figcaption></figure><figure><img tabindex="0" role="button" title="사진 확대" style="cursor:zoom-in" v-if="selfie" :src="selfie" alt="가입 심사용 셀피"/><figcaption>셀피 · 요청한 손동작 확인</figcaption></figure></div><p v-if="data?.photosAvailable">자동 일치 판정은 아닙니다. 조명·화장 차이를 고려해 확인하고, 불확실하면 보완을 요청하세요.</p><template v-if="data?.state==='PENDING'&&data.photosAvailable"><label>코멘트 (보완 요청 시 필수)<textarea v-model="note" maxlength="1000"/></label><div class="actions"><button type="button" :disabled="busy||!selfie||!reference" @click="decide(true)">확인 완료</button><button type="button" :disabled="busy||!note.trim()" @click="decide(false)">셀피 보완 요청</button></div></template><p v-if="error" role="alert">{{error}}</p></section></template>
<script setup>
import {ref,watch,onUnmounted} from 'vue';import api from '../api/api';
const props=defineProps({userId:Number,active:Boolean});const emit=defineEmits(['state']);const requested=ref(false),requestReason=ref("");const data=ref(),selfie=ref(''),reference=ref(''),busy=ref(false),note=ref(''),error=ref('');let epoch=0;
const labels={REQUESTED:'셀피 요청됨',PENDING:'셀피 심사 대기',APPROVED:'셀피 수동 확인 완료',RETRY:'셀피 보완 요청',PHOTO_CHANGED:'대표 사진 변경 · 재촬영 필요',WITHDRAWN:'동의 철회됨',EXPIRED:'보관 기한 만료',CAPTURE:'촬영 대기'};
function release(){epoch++;if(selfie.value)URL.revokeObjectURL(selfie.value);if(reference.value)URL.revokeObjectURL(reference.value);selfie.value=reference.value='';}
async function load(){release();data.value=null;emit('state',null);note.value='';error.value='';if(!props.active)return;const current=epoch;busy.value=true;try{const [review,request]=await Promise.all([api.get(`/admin/selfies/user/${props.userId}`),api.get(`/admin/selfies/user/${props.userId}/request`)]);const row=review.data;requested.value=request.data.required;if(current!==epoch)return;data.value=row;emit('state',row?.state);if(row?.photosAvailable){const photos=await Promise.all([api.get(`/admin/selfies/${row.id}/photo`,{responseType:'blob'}),api.get(`/admin/selfies/${row.id}/photo`,{params:{reference:true},responseType:'blob'})]);if(current!==epoch)return;selfie.value=URL.createObjectURL(photos[0].data);reference.value=URL.createObjectURL(photos[1].data);}}catch(e){if(current===epoch)error.value=e.response?.data?.message||'셀피를 불러오지 못했습니다.';}finally{if(current===epoch)busy.value=false;}}
async function requestSelfie(){busy.value=true;error.value='';try{await api.post(`/admin/selfies/user/${props.userId}/request`,{reason:requestReason.value});requestReason.value='';await load();window.dispatchEvent(new Event('admin-selfies-changed'));}catch(e){error.value=e.response?.data?.message||'요청하지 못했습니다.';}finally{busy.value=false;}}
async function cancelRequest(){busy.value=true;try{await api.delete(`/admin/selfies/user/${props.userId}/request`);await load();window.dispatchEvent(new Event('admin-selfies-changed'));}catch(e){error.value=e.response?.data?.message||'취소하지 못했습니다.';}finally{busy.value=false;}}
async function decide(approve){if(busy.value)return;busy.value=true;try{await api.put(`/admin/selfies/${data.value.id}`,{approve,note:note.value});await load();window.dispatchEvent(new Event('admin-selfies-changed'));}catch(e){error.value=e.response?.data?.message||'심사 결과를 저장하지 못했습니다.';}finally{busy.value=false;}}
watch(()=>[props.userId,props.active],load,{immediate:true});onUnmounted(release);
</script><style scoped>.selfie-panel{margin:20px 0;padding:18px;border:1px solid #e6d8ce;border-radius:14px;background:#fffcf9}.compare{display:grid;grid-template-columns:1fr 1fr;gap:12px}.compare figure{margin:0}.compare img{width:100%;height:260px;object-fit:contain;background:#eee}.selfie-panel p,.selfie-panel figcaption{font-size:13px;line-height:1.7}.selfie-panel label{display:grid;gap:8px}.selfie-panel textarea{padding:10px;border:1px solid #ddd;border-radius:8px}.selfie-panel button{font:inherit;padding:10px;border:0;border-radius:8px;background:#ead9cd;cursor:pointer}.actions{display:flex;gap:10px;margin-top:12px}button:disabled{opacity:.5}[role=alert]{color:#a33}</style>